def find_duplicates(lst):
    seen_dict = {item: None for item in lst}
    duplicates = [item for item, _ in seen_dict.items() if lst.count(item) > 1]
    return set(duplicates)

unit_tests:
assert find_duplicates([1, 2, 3, 4, 5]) == set()
assert find_duplicates([1, 2, 2, 3, 4, 4, 5]) == {2, 4}
assert find_duplicates(['apple', 'banana', 'apple']) == {'apple'}

