import itertools
def merge_configs(config_a, config_b):
    helper = lambda a, b: dict(itertools.chain(a.items(), b.items()))
    return helper(config_a, config_b)

unit_tests:
assert merge_configs({'a': 1}, {'b': 2}) == {'a': 1, 'b': 2}
assert merge_configs({'a': 1}, {}) == {'a': 1}
